/**
 * Hatch patterns for chart fills.
 *
 * The Neon palette is a green family on near-black, so hue alone can't
 * separate five stacked series without going off-brand into a rainbow.
 * Pattern carries the identity instead: each series gets a hatch as well
 * as a color, which survives a colorblind reader, a greyscale print, and
 * a screenshot pasted into Slack at half size.
 *
 * Two surfaces need the same texture: SVG charts (areas, bars, radar
 * bands) and HTML bars (a stacked breakdown built from divs). Both are
 * generated here from one list, so a series can't be hatched one way in
 * a chart and another way in the legend beside it.
 */
import type { CSSProperties } from "react";

export type ChartPatternKind =
  | "diagonal"
  | "horizontal"
  | "vertical"
  | "reverse"
  | "grid";

/** Assignment order, matched to --chart-1 through --chart-5. */
export const CHART_PATTERNS: ChartPatternKind[] = [
  "diagonal",
  "horizontal",
  "vertical",
  "reverse",
  "grid",
];

/** The hatch for a series at a given position, wrapping past five. */
export const patternAt = (index: number): ChartPatternKind =>
  CHART_PATTERNS[index % CHART_PATTERNS.length] ?? "diagonal";

/** Pattern tile size in user units; also the CSS gradient period. */
const TILE = 6;
const STROKE = 1;

/** Angle of the CSS gradient that reproduces each SVG hatch. */
const CSS_ANGLE: Record<ChartPatternKind, string> = {
  diagonal: "45deg",
  grid: "45deg",
  horizontal: "0deg",
  reverse: "-45deg",
  vertical: "90deg",
};

/**
 * The same hatch as a CSS background, for bars built from HTML rather
 * than SVG. Returns style props to spread, not a class, so the color
 * stays a runtime value.
 */
export const patternStyle = (
  kind: ChartPatternKind,
  color: string,
  opacity = 0.55
): CSSProperties => {
  const line = `color-mix(in oklch, ${color} ${Math.round(opacity * 100)}%, transparent)`;
  const stripe = `repeating-linear-gradient(${CSS_ANGLE[kind]}, ${line} 0 ${STROKE}px, transparent ${STROKE}px ${TILE}px)`;

  return {
    backgroundImage:
      kind === "grid"
        ? `${stripe}, repeating-linear-gradient(-45deg, ${line} 0 ${STROKE}px, transparent ${STROKE}px ${TILE}px)`
        : stripe,
  };
};

/** Stable id for a pattern def, scoped to the chart instance. */
export const patternId = (scope: string, seriesId: string) =>
  `${scope}-hatch-${seriesId.replaceAll(/[^a-zA-Z0-9_-]/gu, "")}`;

export const patternFill = (scope: string, seriesId: string) =>
  `url(#${patternId(scope, seriesId)})`;

const LINES: Record<
  ChartPatternKind,
  { x1: number; y1: number; x2: number; y2: number }[]
> = {
  diagonal: [{ x1: 0, x2: TILE, y1: TILE, y2: 0 }],
  grid: [
    { x1: 0, x2: TILE, y1: TILE, y2: 0 },
    { x1: 0, x2: TILE, y1: 0, y2: TILE },
  ],
  horizontal: [{ x1: 0, x2: TILE, y1: TILE / 2, y2: TILE / 2 }],
  reverse: [{ x1: 0, x2: TILE, y1: 0, y2: TILE }],
  vertical: [{ x1: TILE / 2, x2: TILE / 2, y1: 0, y2: TILE }],
};

export interface ChartPatternSpec {
  /** Series id the pattern belongs to. */
  id: string;
  kind: ChartPatternKind;
  color: string;
}

/**
 * SVG `<defs>` for a chart's patterns. Each tile paints a tinted ground
 * plus the hatch on top, so a band keeps a readable body when it's thin
 * and gains texture when it's thick.
 */
export const ChartPatternDefs = ({
  patterns,
  scope,
  fillOpacity = 0.22,
  lineOpacity = 0.55,
}: {
  patterns: ChartPatternSpec[];
  /** Instance-unique prefix, e.g. a useId() value. */
  scope: string;
  /** Opacity of the ground behind the hatch. */
  fillOpacity?: number;
  /** Opacity of the hatch lines. */
  lineOpacity?: number;
}) => (
  <defs>
    {patterns.map((pattern) => (
      <pattern
        height={TILE}
        id={patternId(scope, pattern.id)}
        key={pattern.id}
        patternUnits="userSpaceOnUse"
        width={TILE}
      >
        <rect
          fill={pattern.color}
          fillOpacity={fillOpacity}
          height={TILE}
          width={TILE}
          x={0}
          y={0}
        />
        {LINES[pattern.kind].map((line) => (
          <line
            key={`${line.x1}-${line.y1}-${line.x2}-${line.y2}`}
            stroke={pattern.color}
            strokeLinecap="square"
            strokeOpacity={lineOpacity}
            strokeWidth={STROKE}
            x1={line.x1}
            x2={line.x2}
            y1={line.y1}
            y2={line.y2}
          />
        ))}
      </pattern>
    ))}
  </defs>
);
